from lib import *
S = SS('g10')
steps = [
    step("先看源码:Go 1.27.1 的 map 是 Swiss Table 实现(internal/runtime/maps)。常量:maxTableCapacity = 1024(一张表最多 1024 个槽)、maxAvgGroupLoad = 7(每组 8 个槽平均装 7 个,即装载率 7/8)、MapGroupSlots = 8(每组 8 个槽);internal/goexperiment 里已经没有 noswissmap 开关,旧的 hmap 渐进式搬迁实现不在了。", t=tl(S(1)), done=lidx(S(1), 'maxTableCapacity', 'maxAvgGroupLoad', 'MapGroupSlots'), mark=lidx(S(1), 'noswissmap'), kv=KV([['maxTableCapacity', '1024 个槽'], ['maxAvgGroupLoad', '7(每组 8 槽平均装 7 个)'], ['MapGroupSlots', '8'], ['旧实现', 'GOEXPERIMENT 里已无 swissmap 开关']], ['maxTableCapacity'])),
    step("逐个插入 map[int]int 的前 3000 个键,记录 Mallocs 增加的时刻:len = 9 时 +3(第 9 个元素超过一组 8 个槽,从小 map 变成真正的表)、15、29、57、113、225、449 各 +2(即容量 16、32、64、128、256、512 乘 7/8 之后再多一个,表翻倍)、897 时 +5(容量 1024 的表满了:896 之后的下一个)、1793 +5、1794 +4。共 10 次分配增加。", t=tl(S(2)), done=lidx(S(2), '9(+3)'), mark=lidx(S(2), '897(+5)'), b=bars([['len=9', 3, '+3'], ['len=15', 2, '+2'], ['len=449', 2, '+2'], ['len=897', 5, '+5'], ['len=1793', 5, '+5']], 5, done=[0, 1, 2], mark=[3, 4]), kv=KV([['9', '+3:离开单组小 map'], ['15、29、57、113、225、449', '各 +2:容量翻倍(16 到 512 个槽)'], ['897', '+5:容量 1024 的表装满后拆分'], ['1793、1794', '+5、+4:继续拆分']], ['897'])),
    step("单次插入的耗时分布(100 万个键,关掉 GC,逐个计时,time.Now 本身约 40 ns):不给容量提示:p50 42 ns、p99 208 ns、p99.9 16125 ns、最大 80042 ns,最慢的几次发生在 len = 935678(80 µs)、965281(50 µs)、57351(48 µs)、114729(46 µs);make(map[int]int, 1000000):p50 42 ns、p99 167 ns、p99.9 1500 ns、最大 26542 ns。", t=tl(S(3)), done=lidx(S(3), 'make(map[int]int, 1000000)'), mark=lidx(S(3), '不给容量提示'), b=bars([['不给提示 p99.9 ns', 16125, '16125'], ['给提示 p99.9 ns', 1500, '1500'], ['不给提示 最大 µs', 80, '80'], ['给提示 最大 µs', 26.5, '26.5']], 16125, done=[1], mark=[0]), kv=KV([['p50', '42 ns(两种相同)'], ['p99.9', '16125 ns(无提示)/ 1500 ns(有提示)'], ['最大', '80 µs(无提示)/ 26.5 µs(有提示)'], ['最慢插入的位置', '57351、114729 一类的倍增处,也有 935678 这样的']], ['p99.9'])),
    step("map 不会缩小:基线 0.20 MiB;插入 100 万个键后 36.27 MiB;delete 掉全部键后(len = 0)仍是 36.27 MiB;clear(m) 之后回到 0.20 MiB;m = nil 之后 0.20 MiB。", t=tl(S(4)), done=lidx(S(4), '基线'), mark=lidx(S(4), 'clear(m)', 'm = nil'), b=bars([['基线', 0.20, '0.20 MiB'], ['插入 100 万个键', 36.27, '36.27 MiB'], ['delete 全部键之后', 36.27, '36.27 MiB'], ['clear(m) 之后', 0.20, '0.20 MiB']], 36.27, done=[0, 3], mark=[1, 2]), kv=KV([['插入 100 万个 int→int', '36.27 MiB'], ['delete 全部键', '仍是 36.27 MiB'], ['clear(m)', '回到 0.20 MiB'], ['m = nil', '0.20 MiB']], ['delete 全部键'])),
]
A = mkartg('g10', 10, 'Go,map,Swiss Table,扩容,内存,真实验证,动画演示',
    '在 Go 1.27.1 里实测 map 的扩容:map 已是 Swiss Table 实现(旧的渐进式搬迁已移除),插入第 9 个键离开单组小 map,装载率 7/8 时容量依次翻倍,满 1024 个槽的表后拆分;100 万个键不给容量提示时 p99.9 是 16125 ns、最大 80 µs,给容量提示 p99.9 是 1500 ns;delete 全部键内存不回收,clear(m) 才回到 0.20 MiB。',
    '这一篇的题目本来想写“渐进式扩容”,但在 Go 1.27.1 里实际验证后发现 map 已经换成了 Swiss Table,旧的“每次读写顺带搬迁几个桶”的实现已经移除。所以这篇改成验证现在的行为:什么时候扩容、扩容发生在哪几次插入、单次插入的耗时分布,以及 map 为什么不会因为 delete 而缩小。',
    [('7/8', 'maxAvgGroupLoad = 7:每组 8 个槽平均装 7 个时扩容'), ('1024', '一张表最多 1024 个槽,满了就拆分,而不是继续翻倍'), ('36.27 MiB', '100 万个 int→int 的 map;delete 全部键之后依旧是 36.27 MiB')],
    [('源码里的设计', '<p><code>internal/runtime/maps/map.go</code> 开头的注释把设计讲得很清楚(以下是我读到的):键值放在“组”里,每组 8 个槽外加一个 8 字节的控制字,每个字节记录一个槽是空、已删除还是在用,在用时还带着哈希的低 7 位,所以一次位运算就能并行比较 8 个槽;一张表由若干组构成,探测用二次探测;删除时若整组已满就放“墓碑”,墓碑只在扩容时清理。<b>增长是整张表一次完成的</b>(探测序列依赖组数,必须重排),为了让一次增长不至于太大,map 把内容分到多张表里,每张表最大 <code>maxTableCapacity = 1024</code> 个槽:不到上限时增长就是换成两倍容量的新表,到上限后把表拆分成两张,由一个“目录”按哈希高位选表。注释里写的目的是 “to support incremental growth”,所以“渐进”这个词现在指的是“每次增长只涉及一张最多 1024 个槽的表”,而不是旧实现里“分摊到后续读写里逐步搬迁”。</p>'),
     ('扩容发生的时刻', '<p>从 Mallocs 的变化能看出每次扩容:第 9 个元素时从小 map(一个组)变成真正的表,之后每次容量翻倍(15、29、57……449 对应容量 16 到 512 个槽的 7/8 再加一),到容量 1024 的表满了以后(897)就不再翻倍,而是拆分。这些“+2 次、+5 次”的分配数是 Mallocs 计数的直接结果,每个分配分别是什么(组数组、表结构、目录)我没有逐个确认。</p>'),
     ('单次插入的耗时', '<p>绝大多数插入只要几十纳秒(含计时开销),但每次扩容或拆分都会让当次插入变慢。关掉 GC 以后(排除 GC 干扰),不给容量提示的 p99.9 是 16125 ns、最大 80 µs;给容量提示后 p99.9 只有 1500 ns,最大 26.5 µs。注意:最慢的几次发生在哪个 len,每次运行都不完全相同,我没有把它们逐一对应到具体的表拆分或目录扩容上,所以只能说“与扩容有关,不能保证每一次都是”。</p>'),
     ('map 不缩小', '<p><code>delete</code> 只是把槽标成空,不释放表。插入 100 万个键后堆是 36.27 MiB,删光之后还是 36.27 MiB;<code>clear(m)</code> 之后堆回到基线,说明 Go 1.27.1 的 <code>clear</code> 会放弃大的表(这一点是实测结果,我没有读 <code>clear</code> 的实现)。需要真正释放内存时,把 map 置为 <code>nil</code> 或重建一个新 map 同样有效。</p>')],
    steps,
    [ENV_G + '。读过的源码:internal/runtime/maps/map.go 开头的设计注释(术语、探测、删除、增长、目录),以及 table.go、group.go 与 internal/abi/map.go 里的常量(没有逐行读插入、拆分与迭代的实现);Mallocs 来自 runtime.ReadMemStats(先把结果存进预分配的数组,再统一打印,避免打印本身的分配干扰计数);耗时分布是逐次 time.Now 计时、关闭 GC(debug.SetGCPercent(-1))的 100 万次插入,不是基准测试,每次运行位置与数值会有变化;堆的数字每次先 runtime.GC()',
     '没有验证:旧的 hmap 渐进式搬迁实现(1.27.1 里已经不存在,无法对照)、字符串键与大值的 map、遍历与扩容并发时的语义(见下一篇遍历顺序)、amd64 上的耗时、Swiss Table 控制字与 SIMD 匹配的细节'],
    'map 的扩容')
